function mapLabels(entries, mapper, options) {
  const concurrency = options.concurrency;

  if (!Number.isInteger(concurrency) || concurrency < 1 || concurrency > 3) {
    return Promise.reject(new RangeError("concurrency must be an integer from 1 to 3"));
  }

  const keys = Array.from(entries.keys());

  return new Promise((resolve, reject) => {
    const results = new Array(keys.length);
    let nextIndex = 0;
    let active = 0;
    let completed = 0;
    let settled = false;

    const cleanup = () => {
      options.signal.removeEventListener("abort", onAbort);
    };

    const finish = (fn, value) => {
      if (settled) return;
      settled = true;
      cleanup();
      fn(value);
    };

    const onAbort = () => {
      finish(reject, options.signal.reason);
    };

    if (options.signal.aborted) {
      reject(options.signal.reason);
      return;
    }

    options.signal.addEventListener("abort", onAbort);

    const schedule = () => {
      while (
        !settled &&
        active < concurrency &&
        nextIndex < keys.length
      ) {
        const index = nextIndex++;
        const key = keys[index];
        const value = entries.get(key);

        active++;

        let mapped;
        try {
          mapped = mapper(value, key);
        } catch (error) {
          active--;
          finish(reject, error);
          return;
        }

        Promise.resolve(mapped).then(
          result => {
            active--;
            if (settled) return;

            results[index] = result;
            completed++;

            if (completed === keys.length) {
              const output = new Map();
              for (let i = 0; i < keys.length; i++) {
                output.set(keys[i], results[i]);
              }
              finish(resolve, output);
            } else {
              schedule();
            }
          },
          error => {
            active--;
            finish(reject, error);
          }
        );
      }

      if (!settled && keys.length === 0) {
        finish(resolve, new Map());
      }
    };

    schedule();
  });
}
